  const load = () => { try { const raw=localStorage.getItem(STORE);const value=raw?JSON.parse(raw):seed();for(const q of value.quotes||[])if(String(q.token||'').startsWith('qf-demo-'))q.token=crypto.randomUUID();return value; } catch { return seed(); } };
  let db=load(), page='Dashboard', quoteDraft=null, rfqDraft=null, currentFilter='All', account=null, syncTimer=null;
  const save=()=>{if(account){localStorage.setItem(AUTH,JSON.stringify(db));}else{localStorage.setItem(STORE,JSON.stringify(db));clearTimeout(syncTimer);syncTimer=setTimeout(()=>api('/api/demo',{method:'PUT',body:JSON.stringify(db)}).catch(()=>{}),250);}};
  async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const value=await response.json().catch(()=>({}));if(!response.ok)throw new Error(value.error||'Request failed.');return value;}
  async function syncAll(){if(!account)return;for(const [key,path] of [['customers','customers'],['products','products'],['rfqs','rfqs'],['followups','followups']])for(const item of db[key]||[])await api(`/api/${path}`,{method:'POST',body:JSON.stringify(item)});for(const q of db.quotes||[]){const value={...q};delete value.organizationId;await api('/api/quotes',{method:'POST',body:JSON.stringify(value)});}await api('/api/settings',{method:'PUT',body:JSON.stringify(db.settings)});}
  async function loadDemo(){try{const serverDemo=await api('/api/demo');if(serverDemo.customers)db=serverDemo;else await api('/api/demo',{method:'PUT',body:JSON.stringify(db)});localStorage.setItem(STORE,JSON.stringify(db));render();}catch{}}
  async function loadAccount(){const me=await api('/api/auth/me');const data=await api('/api/bootstrap');account=me;db={settings:data.settings,customers:data.customers,products:data.products,rfqs:data.rfqs,quotes:data.quotes,followups:data.followups,events:data.events};localStorage.setItem(AUTH,JSON.stringify(db));page='Dashboard';render();}
  const app=document.getElementById('app'), modal=document.getElementById('modal');
