  function renderLanding(){const [title,desc]=landingPages[location.pathname]||['From RFQ to professional quote in minutes','QuoteFlow helps suppliers and service businesses capture requests, price jobs, create polished proposals and follow up — all from one workspace.'];document.title=`${title} — QuoteFlow`;app.innerHTML=`<div style="background:#fff;min-height:100vh"><header style="height:68px;max-width:1160px;margin:auto;padding:0 24px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)">${logo()}<nav style="display:flex;gap:21px;align-items:center;font-size:11px;color:#596577"><a href="/features">Features</a><a href="/pricing">Pricing</a><a href="/rfq-software">For suppliers</a><button class="btn" data-action="enter-demo">Open demo</button></nav></header><section style="max-width:1160px;margin:0 auto;padding:92px 24px 70px;display:grid;grid-template-columns:1.05fr .95fr;gap:46px;align-items:center"><div><div class="eyebrow">RFQ & QUOTATION WORKSPACE FOR B2B TEAMS</div><h1 style="font:800 clamp(34px,5vw,55px)/1.09 Manrope;letter-spacing:-2px;max-width:610px;margin:12px 0 17px">${esc(title)}</h1><p style="font-size:15px;line-height:1.75;color:#667386;max-width:540px">${esc(desc)}</p><div style="display:flex;gap:9px;margin-top:25px"><button class="btn primary" data-action="enter-demo">Try the demo ${icon('arrow')}</button><a href="/features" class="btn">See how it works</a></div><div style="margin-top:16px;font-size:10px;color:#8993a1">No credit card · No signup · Clearly labeled sample data</div></div><div style="background:#f5f7fb;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow)"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><strong style="font:700 12px Manrope">A clearer quoting workflow</strong><span class="badge blue">DEMO VIEW</span></div><div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;align-items:center">${[['RFQ','Request'],['box','Price'],['file','Quote'],['arrow','Share'],['check','Win']].map(([ic,label],i)=>`<div style="background:#fff;border:1px solid var(--line);border-radius:9px;padding:13px 6px;text-align:center"><div style="color:${i===4?'#178361':'#2d5bdb'}">${ic==='RFQ'?'01':icon(ic,16)}</div><div style="font-size:9px;font-weight:600;margin-top:7px">${label}</div></div>`).join('')}</div><div class="panel" style="margin-top:14px;padding:14px"><div style="display:flex;justify-content:space-between;font-size:10px"><b>Q-2026-008 · Guest room workspace</b>${badge('Sent')}</div><div style="color:#8993a1;font-size:9px;margin-top:7px">Horizon Hospitality · Valid until ${niceDate(dateOffset(29))}</div><div style="font:700 18px Manrope;margin-top:14px">${money(quoteMath(getQuote('q1')).total)}</div></div></div></section><section style="background:#f7f8fa;padding:54px 24px"><div style="max-width:1100px;margin:auto;text-align:center"><div class="eyebrow">LESS ADMIN BETWEEN REQUEST AND REVENUE</div><h2 style="font:700 25px Manrope;margin:0">The core work, in one calm workspace.</h2><div class="section-row" style="margin-top:23px;text-align:left"><div class="panel" style="padding:21px"><span class="metric-icon">${icon('inbox')}</span><h3 style="font:700 14px Manrope">Start with the request</h3><p style="font-size:11px;color:#687486;line-height:1.7">Capture an RFQ, add requested items and review extracted suggestions before they become quote lines.</p></div><div class="panel" style="padding:21px"><span class="metric-icon">${icon('chart')}</span><h3 style="font:700 14px Manrope">Price with context</h3><p style="font-size:11px;color:#687486;line-height:1.7">See estimated cost, gross profit and margin while you prepare the offer.</p></div></div><div class="section-row" style="text-align:left"><div class="panel" style="padding:21px"><span class="metric-icon">${icon('file')}</span><h3 style="font:700 14px Manrope">Send a stronger quote</h3><p style="font-size:11px;color:#687486;line-height:1.7">Preview a clean customer-facing document and save it as PDF from your browser.</p></div><div class="panel" style="padding:21px"><span class="metric-icon">${icon('calendar')}</span><h3 style="font:700 14px Manrope">Keep the follow-up visible</h3><p style="font-size:11px;color:#687486;line-height:1.7">Track customer responses and due tasks instead of losing the next step in a mailbox.</p></div></div></div></section><section style="padding:52px 24px;text-align:center"><div class="eyebrow">A FOCUSED START</div><h2 style="font:700 23px Manrope">Try the sample workspace</h2><p style="font-size:11px;color:#687486">Explore demo dashboard, RFQs, quotes, customer portal and follow-ups. All records are fictional.</p><button class="btn primary" data-action="enter-demo">Open QuoteFlow demo ${icon('arrow')}</button><p style="font-size:9px;color:#929baa;margin-top:19px">Plans are hypotheses for product research. No paid plan or subscription is currently available.</p></section><footer style="border-top:1px solid var(--line);padding:20px 24px;display:flex;justify-content:center;gap:18px;font-size:9px;color:#818c9b"><span>© QuoteFlow demo</span><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/security">Security</a><a href="/contact">Contact</a></footer></div>`;}
  function shell(content){app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar">${logo()}<div class="org-switch"><div class="org-avatar">AC</div><div class="org-info"><strong>${esc(db.settings.company)}</strong><small>Demo workspace</small></div><span style="margin-left:auto;color:#929baa">⌄</span></div><div class="nav-label">WORKSPACE</div><nav class="nav">${navItems.map(([n,i])=>`<button class="${page===n?'active':''}" data-page="${n}">${icon(i)}${esc(n)}</button>`).join('')}</nav><div class="nav-spacer"></div><div class="nav-label">PREFERENCES</div><nav class="nav"><button class="${page==='Settings'?'active':''}" data-page="Settings">${icon('settings')}Settings</button><button data-action="demo-reset">${icon('clock')}Reset demo data</button></nav><div class="side-bottom"><div class="demo-note"><b>Fictional demo workspace</b>Records are saved only in this browser. No real customer or company data is used.</div><div class="user-row"><div class="user-avatar">SM</div><div class="user-meta"><strong>Sarah Mitchell</strong><small>Workspace owner</small></div><button class="icon-btn" aria-label="Settings" data-page="Settings">${icon('settings')}</button></div></div></aside><section class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn mobile-menu" id="menu-toggle" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">Workspace <span style="margin:0 7px;color:#bdc4ce">/</span> <b>${esc(page)}</b></div></div><div class="top-actions"><button class="icon-btn" aria-label="Search" data-action="global-search">${icon('search')}</button><button class="icon-btn" aria-label="Notifications" data-page="Follow-ups">${icon('bell')}</button><button class="btn primary" data-action="new-rfq">${icon('plus')} New RFQ</button></div></header><div class="content">${content}</div></section></div>`;}
  const head=(kicker,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
  const actionBtn=(action,label,cls='')=>`<button class="btn ${cls}" data-action="${action}">${label}</button>`;
  function render(){if(location.pathname.startsWith('/q/'))return renderPortal(decodeURIComponent(location.pathname.split('/').pop()));if(location.pathname==='/login'&&!document.querySelector('.app-shell'))return renderLogin();const views={'Dashboard':dashboard,'RFQs':rfqsPage,'Quotations':quotesPage,'Customers':customersPage,'Products & services':productsPage,'Analytics':analyticsPage,'Follow-ups':followupsPage,'Settings':settingsPage};shell((views[page]||dashboard)());window.scrollTo(0,0);}
  function dashboard(){const openRFQ=db.rfqs.filter(x=>!['Won','Lost','Expired','Cancelled'].includes(x.status)).length;const drafts=db.quotes.filter(x=>x.status==='Draft').length;const sent=db.quotes.filter(x=>['Sent','Viewed'].includes(x.status)).length;const won=db.quotes.filter(x=>['Accepted','Won'].includes(x.status));const decided=db.quotes.filter(x=>['Accepted','Won','Rejected','Lost'].includes(x.status));const win=decided.length?Math.round(won.length/decided.length*100):0;const pipe=db.quotes.filter(x=>['Draft','Sent','Viewed'].includes(x.status)).reduce((a,q)=>a+quoteMath(q).total,0);const recent=[...db.rfqs].sort((a,b)=>b.received.localeCompare(a.received)).slice(0,4);const tasks=db.followups.filter(x=>x.status==='Pending').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4);const max=Math.max(1,...[...Array(6)].map((_,i)=>db.quotes.filter(q=>q.created?.slice(5,7)===String(((new Date().getMonth()-5+i+12)%12)+1).padStart(2,'0')).length));const greetingDate=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});return `${head(greetingDate,'Good morning, Sarah','Here’s what’s moving across your workspace.',actionBtn('new-quote',`${icon('plus')} New quote`,'primary'))}<div class="metric-grid"><div class="metric"><div class="metric-top">Open RFQs <span class="metric-icon">${icon('inbox')}</span></div><div class="metric-value">${openRFQ}</div><div class="metric-foot">Requests still in progress</div></div><div class="metric"><div class="metric-top">Draft quotes <span class="metric-icon">${icon('file')}</span></div><div class="metric-value">${drafts}</div><div class="metric-foot">Ready for a final review</div></div><div class="metric"><div class="metric-top">Awaiting response <span class="metric-icon">${icon('clock')}</span></div><div class="metric-value">${sent}</div><div class="metric-foot">Sent to customers</div></div><div class="metric"><div class="metric-top">Win rate <span class="metric-icon">${icon('chart')}</span></div><div class="metric-value">${win}%</div><div class="metric-foot">${won.length} won · ${decided.length} decided</div></div></div><div class="dashboard-columns"><section class="panel"><div class="panel-head"><h2>Recent RFQs</h2><a data-page="RFQs">View all →</a></div>${recent.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>REQUEST</th><th>CUSTOMER</th><th>DEADLINE</th><th>STATUS</th></tr></thead><tbody>${recent.map(r=>`<tr data-open-rfq="${r.id}"><td class="primary-cell">${esc(r.title)}<div class="muted" style="font-size:9px;margin-top:4px">${esc(r.number)}</div></td><td>${esc(customerName(r.customerId))}</td><td>${niceDate(r.deadline)}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No RFQs yet','Start with a request from a customer, then build a quote from it.','new-rfq','Create RFQ')}</section><section class="panel"><div class="panel-head"><h2>Quote pipeline</h2><a data-page="Analytics">Details →</a></div><div class="pipeline"><div class="pipeline-total">${money(pipe)}</div><div class="pipeline-label">Open quotation value</div><div class="bar-chart">${[0,1,2,3,4,5].map((v)=>{const n=db.quotes.filter(q=>q.created?.slice(5,7)===String(((new Date().getMonth()-5+v+12)%12)+1).padStart(2,'0')).length;return `<div class="bar-col"><div class="bar ${v===5?'current':''}" style="height:${Math.max(6,n/max*72)}%" title="${n} quotes"></div><span>${new Date(new Date().getFullYear(),(new Date().getMonth()-5+v+12)%12,1).toLocaleDateString('en-US',{month:'short'})}</span></div>`}).join('')}</div><div class="legend"><i></i>Quotes created · ${db.quotes.length} total</div></div></section></div><div class="section-row"><section class="panel"><div class="panel-head"><h2>Recent quotations</h2><a data-page="Quotations">View all →</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>QUOTE</th><th>CUSTOMER</th><th>VALUE</th><th>STATUS</th></tr></thead><tbody>${[...db.quotes].sort((a,b)=>b.created.localeCompare(a.created)).slice(0,4).map(q=>`<tr data-open-quote="${q.id}"><td class="primary-cell">${esc(q.number)}</td><td>${esc(customerName(q.customerId))}</td><td>${money(quoteMath(q).total,q.currency)}</td><td>${badge(q.status)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Follow-ups</h2><a data-page="Follow-ups">View all →</a></div><div class="follow-list">${tasks.length?tasks.map(f=>{const q=getQuote(f.quoteId);return `<div class="follow-row"><button class="follow-check" aria-label="Complete follow-up" data-complete-follow="${f.id}"></button><div class="follow-info"><strong>${esc(f.title)}</strong><small>${esc(q?.number||'Quote')} · ${esc(customerName(q?.customerId))}</small></div><span class="due">${f.due<=dateOffset(0)?'Today':niceDate(f.due)}</span></div>`}).join(''):`<div class="empty-state" style="padding:24px 4px"><h3>All caught up</h3><p>No pending follow-ups right now.</p></div>`}</div></section></div>`;}
  function empty(title,desc,action,label){return `<div class="empty-state"><div class="empty-icon">${icon('file')}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p><button class="btn primary" data-action="${action}">${icon('plus')}${esc(label)}</button></div>`;}
  function rfqsPage(){const list=db.rfqs.filter(r=>currentFilter==='All'||r.status===currentFilter);return `${head('SALES WORKSPACE','RFQs','Capture customer requests and keep the next step clear.',actionBtn('new-rfq',`${icon('plus')} New RFQ`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search RFQs or customers…"/><div class="filter-row"><select class="select" id="status-filter"><option>All</option>${['New','Reviewing','Pricing','Quoted','Won','Lost','Expired','Cancelled'].map(s=>`<option ${currentFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn" data-action="import-rfq">${icon('plus')} Paste RFQ</button></div></div><div id="rfq-table">${rfqTable(list)}</div></section>`;}
  function rfqTable(list){return list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>RFQ</th><th>CUSTOMER</th><th>RECEIVED</th><th>DEADLINE</th><th>PRIORITY</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(r=>`<tr data-open-rfq="${r.id}"><td class="primary-cell">${esc(r.title)}<div class="muted" style="font-size:9px;margin-top:4px">${esc(r.number)}</div></td><td>${esc(customerName(r.customerId))}</td><td>${niceDate(r.received)}</td><td>${niceDate(r.deadline)}</td><td>${esc(r.priority)}</td><td>${badge(r.status)}</td><td><button class="btn" data-convert-rfq="${r.id}">Make quote</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Showing ${list.length} RFQs</span><span>Records stored in this browser</span></div>`:empty('No matching RFQs','Try another search or capture a new customer request.','new-rfq','Create RFQ');}
  function quotesPage(){const list=db.quotes.filter(q=>currentFilter==='All'||q.status===currentFilter);return `${head('SALES WORKSPACE','Quotations','Build clear offers, track responses and follow up at the right time.',actionBtn('new-quote',`${icon('plus')} New quote`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search quotes or customers…"/><div class="filter-row"><select class="select" id="status-filter"><option>All</option>${['Draft','Sent','Viewed','Accepted','Rejected','Expired'].map(s=>`<option ${currentFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn" data-action="export-quotes">${icon('download')} Export CSV</button></div></div><div id="quote-table">${quoteTable(list)}</div></section>`;}
  function quoteTable(list){return list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>QUOTE</th><th>CUSTOMER</th><th>CREATED</th><th>VALID UNTIL</th><th>VALUE</th><th>MARGIN</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(q=>{const m=quoteMath(q);return `<tr data-open-quote="${q.id}"><td class="primary-cell">${esc(q.title)}<div class="muted" style="font-size:9px;margin-top:4px">${esc(q.number)}</div></td><td>${esc(customerName(q.customerId))}</td><td>${niceDate(q.created)}</td><td>${niceDate(q.expiry)}</td><td>${money(m.total,q.currency)}</td><td>${m.margin.toFixed(1)}%</td><td>${badge(q.status)}</td><td><button class="btn" data-preview-quote="${q.id}">Preview</button></td></tr>`}).join('')}</tbody></table></div><div class="table-footer"><span>Showing ${list.length} quotations</span><span>${db.quotes.length} total</span></div>`:empty('No quotations yet','Create a quote directly or turn an RFQ into a priced offer.','new-quote','Create quote');}
  function customersPage(){return `${head('RELATIONSHIPS','Customers','Keep contacts and commercial activity together.',actionBtn('new-customer',`${icon('plus')} Add customer`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search customers…"/><button class="btn" data-action="export-customers">${icon('download')} Export CSV</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>COMPANY</th><th>CONTACT</th><th>EMAIL</th><th>INDUSTRY</th><th>QUOTES</th><th>WON VALUE</th><th></th></tr></thead><tbody id="customer-table">${customerRows(db.customers)}</tbody></table></div><div class="table-footer"><span>${db.customers.length} customers</span><span>Demo customer details use reserved .example domains</span></div></section>`;}
  function customerRows(list){return list.length?list.map(c=>{const qs=db.quotes.filter(q=>q.customerId===c.id);const won=qs.filter(q=>['Accepted','Won'].includes(q.status)).reduce((a,q)=>a+quoteMath(q).total,0);return `<tr data-open-customer="${c.id}"><td class="primary-cell">${esc(c.name)}</td><td>${esc(c.contact||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.industry||'—')}</td><td>${qs.length}</td><td>${money(won)}</td><td><button class="btn" data-customer-edit="${c.id}">View</button></td></tr>`}).join(''):`<tr><td colspan="7">${empty('No customers yet','Add a customer before preparing your first quote.','new-customer','Add customer')}</td></tr>`;}
  function productsPage(){return `${head('CATALOG','Products & services','Reusable line items for goods, labor and service work.',actionBtn('new-product',`${icon('plus')} Add item`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search by item, SKU or category…"/><div class="filter-row"><button class="btn" data-action="import-csv">${icon('plus')} Import CSV</button><button class="btn" data-action="export-products">${icon('download')} Export CSV</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ITEM</th><th>SKU</th><th>CATEGORY</th><th>UNIT</th><th>COST</th><th>SELLING PRICE</th><th>GROSS MARGIN</th></tr></thead><tbody id="product-table">${productRows(db.products)}</tbody></table></div><div class="table-footer"><span>${db.products.length} active items</span><span>Prices shown in ${esc(db.settings.currency)}</span></div></section>`;}
  function productRows(list){return list.length?list.map(p=>`<tr data-product-edit="${p.id}"><td class="primary-cell">${esc(p.name)}<div class="muted" style="font-size:9px;margin-top:4px">${esc(p.description)}</div></td><td>${esc(p.sku)}</td><td>${esc(p.category)}</td><td>${esc(p.unit)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${p.price?((p.price-p.cost)/p.price*100).toFixed(1):'0.0'}%</td></tr>`).join(''):`<tr><td colspan="7">${empty('No catalog items','Add a product or service to price quotes more quickly.','new-product','Add item')}</td></tr>`;}
  function analyticsPage(){const decided=db.quotes.filter(q=>['Accepted','Won','Rejected','Lost'].includes(q.status));const won=db.quotes.filter(q=>['Accepted','Won'].includes(q.status));const sent=db.quotes.filter(q=>['Sent','Viewed','Accepted','Won','Rejected','Lost'].includes(q.status));const value=db.quotes.reduce((s,q)=>s+quoteMath(q).total,0);const wonValue=won.reduce((s,q)=>s+quoteMath(q).total,0);const margins=db.quotes.filter(q=>q.items.length).map(q=>quoteMath(q).margin);const avgMargin=margins.length?margins.reduce((a,b)=>a+b,0)/margins.length:0;return `${head('PERFORMANCE','Analytics','A clear view of actual quotation activity in this demo workspace.')}<div class="metric-grid"><div class="metric"><div class="metric-top">Quotes created <span class="metric-icon">${icon('file')}</span></div><div class="metric-value">${db.quotes.length}</div><div class="metric-foot">Stored quote records</div></div><div class="metric"><div class="metric-top">Quoted value <span class="metric-icon">${icon('chart')}</span></div><div class="metric-value" style="font-size:19px">${money(value)}</div><div class="metric-foot">All quote statuses</div></div><div class="metric"><div class="metric-top">Won value <span class="metric-icon">${icon('check')}</span></div><div class="metric-value" style="font-size:19px">${money(wonValue)}</div><div class="metric-foot">${won.length} accepted quotes</div></div><div class="metric"><div class="metric-top">Average gross margin <span class="metric-icon">${icon('chart')}</span></div><div class="metric-value">${avgMargin.toFixed(1)}%</div><div class="metric-foot">Calculated from saved lines</div></div></div><div class="dashboard-columns"><section class="panel"><div class="panel-head"><h2>Quotation outcomes</h2><span class="muted" style="font-size:10px">${decided.length} decided</span></div><div class="pipeline" style="padding:22px"><div style="display:grid;gap:16px">${[['Accepted',won.length,'green'],['Rejected',db.quotes.filter(q=>q.status==='Rejected').length,'red'],['Awaiting response',db.quotes.filter(q=>['Sent','Viewed'].includes(q.status)).length,'blue'],['Draft',db.quotes.filter(q=>q.status==='Draft').length,'gray']].map(([name,n,color])=>`<div><div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:7px"><span>${badge(name)}</span><b>${n}</b></div><div style="height:6px;background:#f0f2f5;border-radius:5px"><div style="width:${db.quotes.length?n/db.quotes.length*100:0}%;height:100%;background:${color==='green'?'#178361':color==='red'?'#bd4b50':color==='blue'?'#2d5bdb':'#9aa3af'};border-radius:5px"></div></div></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>Commercial snapshot</h2></div><div class="detail-card"><div class="customer-stat"><span>RFQs received</span><b>${db.rfqs.length}</b></div><div class="customer-stat"><span>Customers</span><b>${db.customers.length}</b></div><div class="customer-stat"><span>Win rate</span><b>${decided.length?Math.round(won.length/decided.length*100):0}%</b></div><div class="customer-stat"><span>Average quote value</span><b>${money(db.quotes.length?value/db.quotes.length:0)}</b></div><p style="font-size:9px;color:#8993a1;line-height:1.6;margin-top:14px">Metrics use the saved demo records in this browser. Open quotes are excluded from the win-rate denominator.</p></div></section></div>`;}
  function followupsPage(){const list=[...db.followups].sort((a,b)=>a.due.localeCompare(b.due));return `${head('SALES WORKSPACE','Follow-ups','Make the next customer touch visible and easy to complete.',actionBtn('new-followup',`${icon('plus')} Add follow-up`,'primary'))}<section class="panel"><div class="panel-head"><h2>Follow-up tasks</h2><span style="font-size:10px;color:#8993a1">${db.followups.filter(f=>f.status==='Pending').length} pending</span></div>${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>TASK</th><th>QUOTE</th><th>CUSTOMER</th><th>DUE</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(f=>{const q=getQuote(f.quoteId);return `<tr><td class="primary-cell">${esc(f.title)}<div class="muted" style="font-size:9px;margin-top:4px">${esc(f.note||'')}</div></td><td>${esc(q?.number||'—')}</td><td>${esc(customerName(q?.customerId))}</td><td>${niceDate(f.due)}</td><td>${badge(f.status)}</td><td>${f.status==='Pending'?`<button class="btn" data-complete-follow="${f.id}">Complete</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:empty('No follow-ups yet','Add a reminder to keep a quotation moving.','new-followup','Add follow-up')}</section>`;}
  function settingsPage(){return `${head('WORKSPACE','Company settings','Set sensible defaults for the quotes your team prepares.',`<button class="btn primary" data-action="save-settings">${icon('check')} Save settings</button>`)}<div class="settings-grid"><section class="panel setting-card"><h3>Company profile</h3><div class="field"><label for="set-company">Company name</label><input id="set-company" value="${esc(db.settings.company)}"/></div><div class="field"><label for="set-email">Business email</label><input id="set-email" type="email" value="${esc(db.settings.email)}"/></div><div class="field"><label for="set-phone">Phone</label><input id="set-phone" value="${esc(db.settings.phone)}"/></div><div class="field"><label for="set-address">Address</label><textarea id="set-address">${esc(db.settings.address)}</textarea></div></section><section class="panel setting-card"><h3>Commercial defaults</h3><div class="field"><label for="set-currency">Default currency</label><select id="set-currency">${['AED','USD','EUR','GBP','SAR'].map(c=>`<option ${db.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="set-tax">Default tax rate (%)</label><input id="set-tax" type="number" min="0" max="100" value="${+db.settings.tax||0}"/></div><div class="field"><label for="set-margin">Minimum gross margin (%)</label><input id="set-margin" type="number" min="0" max="100" value="${+db.settings.margin||0}"/></div><div class="field"><label for="set-validity">Quote validity (days)</label><input id="set-validity" type="number" min="1" max="365" value="${+db.settings.validity||30}"/></div></section><section class="panel setting-card"><h3>Terms shown on new quotes</h3><div class="field"><label for="set-payment">Payment terms</label><input id="set-payment" value="${esc(db.settings.payment)}"/></div><div class="field"><label for="set-delivery">Delivery terms</label><textarea id="set-delivery">${esc(db.settings.delivery)}</textarea></div><div class="field"><label for="set-template">Quote template</label><select id="set-template">${['Modern','Corporate','Minimal'].map(t=>`<option ${db.settings.template===t?'selected':''}>${t}</option>`).join('')}</select></div></section><section class="panel setting-card"><h3>Connected services</h3><p style="font-size:10px;color:#697587;line-height:1.7">This local demo has no configured AI, email, payment or file-storage provider. Quote PDFs can be printed or saved from the document preview. The AI extraction action includes a deterministic local parser.</p><div class="customer-stat"><span>AI provider</span><b>Not configured</b></div><div class="customer-stat"><span>Email sending</span><b>Not configured</b></div><div class="customer-stat"><span>Billing</span><b>Not configured</b></div></section></div>`;}
  function showModal(title,body,foot=''){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;modal.showModal();}
  function field(label,id,value='',type='text',opts={}){return `<div class="field ${opts.full?'full':''}"><label for="${id}">${esc(label)}</label>${type==='textarea'?`<textarea id="${id}" ${opts.required?'required':''}>${esc(value)}</textarea>`:type==='select'?`<select id="${id}" ${opts.required?'required':''}>${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input id="${id}" type="${type}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step?`step="${opts.step}"`:''}/>`}</div>`;}
  function addCustomerModal(){showModal('Add customer',`<form id="customer-form" class="form-grid">${field('Company name','c-name','','text',{required:true,full:true})}${field('Contact name','c-contact')}${field('Email','c-email','', 'email')}${field('Phone','c-phone')}${field('Industry','c-industry')}${field('Address','c-address','','text',{full:true})}${field('Notes','c-notes','','textarea',{full:true})}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-customer">Save customer</button>`);}
  function addProductModal(product=null){showModal(product?'Edit catalog item':'Add product or service',`<form id="product-form" class="form-grid">${field('Item name','p-name',product?.name||'','text',{required:true,full:true})}${field('SKU / item code','p-sku',product?.sku||'')}${field('Category','p-category',product?.category||'Products')}${field('Unit','p-unit',product?.unit||'each')}${field('Cost price','p-cost',product?.cost??0,'number',{min:0,step:'0.01'})}${field('Selling price','p-price',product?.price??0,'number',{min:0,step:'0.01'})}${field('Description','p-description',product?.description||'','textarea',{full:true})}</form><input type="hidden" id="p-edit-id" value="${product?.id||''}"/>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-product">Save item</button>`);}
  function addRfqModal(r=null){showModal(r?'Edit RFQ':'Create RFQ',`<form id="rfq-form" class="form-grid">${field('Request title','r-title',r?.title||'','text',{required:true,full:true})}${field('Customer','r-customer',r?.customerId||db.customers[0]?.id||'','select',{required:true,options:db.customers.map(c=>[c.id,c.name])})}${field('Received','r-received',r?.received||dateOffset(0),'date',{required:true})}${field('Deadline','r-deadline',r?.deadline||dateOffset(7),'date')}${field('Priority','r-priority',r?.priority||'Normal','select',{options:[['Normal','Normal'],['High','High'],['Urgent','Urgent']]})}${field('Status','r-status',r?.status||'New','select',{options:['New','Reviewing','Pricing','Quoted','Won','Lost','Expired','Cancelled'].map(x=>[x,x])})}${field('Source','r-source',r?.source||'Email')}${field('Notes','r-notes',r?.notes||'','textarea',{full:true})}</form><input type="hidden" id="r-edit-id" value="${r?.id||''}"/>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-rfq">Save RFQ</button>`);}
  function importRfqModal(){showModal('Capture an RFQ',`<form id="import-form"><div class="field"><label for="import-customer">Customer</label><select id="import-customer">${db.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label for="rfq-text">Paste the request</label><textarea id="rfq-text" placeholder="Please quote 24 ergonomic task chairs and 6 executive desks. Delivery to Dubai by 30 November." style="height:150px" required></textarea></div><div style="font-size:10px;color:#8993a1;line-height:1.6;margin-top:9px">Local extraction suggests item names and quantities from lines like “24 Aero Task Chair”. Review all extracted items before creating a quotation.</div><div id="extraction-preview" style="margin-top:12px"></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn" data-action="parse-rfq">${icon('spark')} Extract items</button><button class="btn primary" data-action="save-imported-rfq">Create RFQ</button>`);}
  function itemFromProduct(p,qty=1){return {name:p.name,sku:p.sku,description:p.description,qty,unit:p.unit,cost:+p.cost||0,price:+p.price||0,tax:+db.settings.tax||0};}
  function newQuote(rfq=null){if(!db.customers.length){toast('Add a customer first.','error');return addCustomerModal();}quoteDraft=rfq?.quoteId?{...getQuote(rfq.quoteId),items:getQuote(rfq.quoteId).items.map(i=>({...i}))}:{id:null,number:`Q-${new Date().getFullYear()}-${String(db.quotes.length+1).padStart(3,'0')}`,customerId:rfq?.customerId||db.customers[0].id,title:rfq?.title||'',created:dateOffset(0),expiry:dateOffset(+db.settings.validity||30),status:'Draft',currency:db.settings.currency,tax:+db.settings.tax||0,discount:0,payment:db.settings.payment,delivery:db.settings.delivery,notes:'',rfqId:rfq?.id||null,token:crypto.randomUUID(),items:rfq?.items?.length?rfq.items.map(i=>({...i})):[]};page='Quotations';renderQuoteEditor();}
  function renderQuoteEditor(){const q=quoteDraft,m=quoteMath(q);const form=`<section class="panel form-panel"><h3>Quote details</h3><div class="form-grid">${field('Quote title','q-title',q.title,'text',{required:true,full:true})}${field('Customer','q-customer',q.customerId,'select',{options:db.customers.map(c=>[c.id,c.name])})}${field('Currency','q-currency',q.currency,'select',{options:['AED','USD','EUR','GBP','SAR'].map(x=>[x,x])})}${field('Issue date','q-date',q.created,'date')}${field('Valid until','q-expiry',q.expiry,'date')}${field('Payment terms','q-payment',q.payment,'text',{full:true})}${field('Delivery terms','q-delivery',q.delivery,'text',{full:true})}</div><div class="line-head"><h3>Line items</h3><div style="display:flex;gap:6px"><button class="btn" data-action="add-quote-item">${icon('plus')} Add line</button><button class="btn" data-action="add-from-catalog">Add from catalog</button></div></div><div class="line-editor"><table><thead><tr><th>DESCRIPTION</th><th>QTY</th><th>UNIT</th><th>COST</th><th>PRICE</th><th>TAX %</th><th></th></tr></thead><tbody>${q.items.map((i,n)=>`<tr><td><input class="line-name" data-item="${n}" data-key="name" value="${esc(i.name)}" aria-label="Line item description"/><input class="line-name" style="margin-top:4px;color:#8993a1" data-item="${n}" data-key="description" value="${esc(i.description)}" aria-label="Line item detail"/></td><td><input type="number" min="0" step="0.01" data-item="${n}" data-key="qty" value="${i.qty}" aria-label="Quantity"/></td><td><input data-item="${n}" data-key="unit" value="${esc(i.unit)}" aria-label="Unit"/></td><td><input type="number" min="0" step="0.01" data-item="${n}" data-key="cost" value="${i.cost}" aria-label="Cost price"/></td><td><input type="number" min="0" step="0.01" data-item="${n}" data-key="price" value="${i.price}" aria-label="Selling price"/></td><td><input type="number" min="0" max="100" step="0.1" data-item="${n}" data-key="tax" value="${i.tax}" aria-label="Tax rate"/></td><td><button class="line-remove" data-remove-item="${n}" aria-label="Remove line">×</button></td></tr>`).join('')}</tbody></table></div>${field('Quote-wide discount','q-discount',q.discount,'number',{min:0,step:'0.01'})}${field('Notes for customer','q-notes',q.notes,'textarea',{full:true})}</section>`;const under=m.margin<(+db.settings.margin||0);const side=`<aside class="panel summary-card"><h3>Price summary</h3><div class="sum-row"><span>Subtotal</span><strong>${money(m.subtotal,q.currency)}</strong></div><div class="sum-row"><span>Discount</span><strong>− ${money(m.discount,q.currency)}</strong></div><div class="sum-row"><span>Tax</span><strong>${money(m.tax,q.currency)}</strong></div><div class="sum-row sum-total"><span>Total</span><strong>${money(m.total,q.currency)}</strong></div><div class="sum-row" style="margin-top:9px"><span>Estimated cost</span><strong>${money(m.cost,q.currency)}</strong></div><div class="sum-row"><span>Gross profit</span><strong>${money(m.profit,q.currency)}</strong></div><div class="margin-box ${under?'warning':''}">${under?'Margin below configured minimum':'Gross margin'} · ${m.margin.toFixed(1)}%<br>${under?`Your ${+db.settings.margin}% margin guideline may not be met.`:'Margin is calculated from the listed selling prices and costs.'}</div><div class="summary-actions"><button class="btn primary" data-action="save-quote">${icon('check')} Save quote</button><button class="btn" data-action="preview-draft">Preview quote</button><button class="btn" data-action="draft-followup">${icon('spark')} Draft follow-up</button></div><div style="font-size:9px;color:#929baa;line-height:1.6;margin-top:11px">Prices and margin are estimates. Verify tax treatment before sending.</div></aside>`;shell(`${head('QUOTE BUILDER',q.id?'Edit quotation':'New quotation','Prepare a priced offer with a clear view of margin.',`<button class="btn" data-page="RFQs">Back to RFQs</button>`)}<div class="quote-builder">${form}${side}</div>`);}
  function addQuoteItem(){quoteDraft.items.push({name:'',sku:'',description:'',qty:1,unit:'each',cost:0,price:0,tax:+db.settings.tax||0});renderQuoteEditor();}
  function quoteDocument(q,portal=false){const c=getCustomer(q.customerId)||{};const m=quoteMath(q);return `<div class="paper"><div class="paper-brand"><div><div class="paper-logo"><span class="brand-mark">${icon('file',17)}</span>${esc(db.settings.company)}</div><div class="paper-tag">${esc(db.settings.tagline)}</div></div><div><div class="quote-word">QUOTATION</div><div class="quote-meta">${esc(q.number)}<br>Issued ${niceDate(q.created)}<br>Valid until ${niceDate(q.expiry)}</div></div></div><div class="paper-parties"><div><div class="paper-label">Prepared for</div><strong>${esc(c.name||'Customer')}</strong><p>${esc(c.contact||'')}<br>${esc(c.email||'')}<br>${esc(c.address||'')}</p></div><div><div class="paper-label">Prepared by</div><strong>${esc(db.settings.company)}</strong><p>${esc(db.settings.address)}<br>${esc(db.settings.email)} · ${esc(db.settings.phone)}</p></div></div><h2>${esc(q.title||'Quotation')}</h2><table><thead><tr><th style="width:44%">ITEM / DESCRIPTION</th><th>QTY</th><th>UNIT PRICE</th><th>TAX</th><th class="right">AMOUNT</th></tr></thead><tbody>${q.items.map(i=>`<tr><td><strong>${esc(i.name||'Item')}</strong>${i.sku?`<div style="font-size:8px;color:#929baa;margin-top:3px">${esc(i.sku)}</div>`:''}<div style="margin-top:4px;line-height:1.5">${esc(i.description||'')}</div></td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>${money(i.price,q.currency)}</td><td>${+i.tax||0}%</td><td class="right">${money(Math.max(0,+i.qty||0)*Math.max(0,+i.price||0),q.currency)}</td></tr>`).join('')}</tbody></table><div class="paper-totals"><div><span>Subtotal</span><span>${money(m.subtotal+m.discount,q.currency)}</span></div>${m.discount?`<div><span>Discount</span><span>− ${money(m.discount,q.currency)}</span></div>`:''}<div><span>Tax</span><span>${money(m.tax,q.currency)}</span></div><div><span>Total ${esc(q.currency)}</span><span>${money(m.total,q.currency)}</span></div></div><div class="paper-terms"><strong>Payment</strong> · ${esc(q.payment||'As agreed')}<br><strong>Delivery</strong> · ${esc(q.delivery||'As agreed')}${q.notes?`<br><strong>Note</strong> · ${esc(q.notes)}`:''}<br><br>Thank you for the opportunity to provide this quotation. Please contact us if you have any questions about this offer.</div><div class="paper-footer"><span>${esc(db.settings.company)} · ${esc(db.settings.email)}</span><span>${esc(q.number)} · Page 1</span></div></div>`;}
  function quotePreview(q,back='Quotations'){const canAct=['Draft','Sent','Viewed'].includes(q.status);const publicPath=account?`/q/${encodeURIComponent(q.token||'')}`:`/q/demo/${encodeURIComponent(q.token||'')}`;shell(`${head('DOCUMENT PREVIEW',q.number,`${customerName(q.customerId)} · ${q.status}`,`<button class="btn" data-page="${back}">← Back</button>${q.status==='Draft'?`<button class="btn" data-action="send-quote" data-quote="${q.id}">Prepare customer link</button>`:`<button class="btn" data-action="copy-link" data-quote="${q.id}">${icon('arrow')} Copy customer link</button>`}<button class="btn primary" data-action="print-quote">${icon('download')} Print / save PDF</button>`)}<div class="preview-wrap">${quoteDocument(q)}</div>${canAct&&q.status!=='Draft'&&q.token?`<section class="panel" style="margin-top:14px;padding:14px;display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#687486">Customer portal preview</span><a class="btn subtle" href="${publicPath}" target="_blank" rel="noopener">Open customer view ↗</a></section>`:''}`);}
  async function renderPortal(token){const demo=location.pathname.startsWith('/q/demo/');let publicQuote=null;try{publicQuote=demo?(await api(`/api/demo/public?token=${encodeURIComponent(token)}`)).quote:(await api(`/api/public/quote/${encodeURIComponent(token)}`)).quote;}catch{app.innerHTML=`<div class="portal"><div class="portal-top">${logo()}<span style="font-size:10px;color:#8993a1">Quote link</span></div><div class="portal-main"><div class="portal-card"><h2>Quotation unavailable</h2><p>This link may have expired or is not valid.</p></div></div></div>`;return;}const q={id:null,token,number:publicQuote.number,title:publicQuote.title,status:publicQuote.status,expiry:publicQuote.expiry,currency:publicQuote.currency,items:publicQuote.items||[],payment:publicQuote.terms?.payment,delivery:publicQuote.terms?.delivery,notes:publicQuote.terms?.notes,customerId:'public',created:dateOffset(0)};const accepted=['Accepted','Won'].includes(q.status),company=publicQuote.company?.name||'QuoteFlow',customer=publicQuote.customer?.name||'Customer',doc=publicDocument(publicQuote);app.innerHTML=`<div class="portal"><div class="portal-top"><div class="paper-logo"><span class="brand-mark">${icon('file',17)}</span>${esc(company)}</div><span style="font-size:10px;color:#8993a1">${accepted?badge('Accepted'):'Quotation for your review'}</span></div><div class="portal-main"><div class="portal-title"><div><h1>Your quotation</h1><p>${esc(q.number)} · ${esc(customer)}</p></div>${q.status==='Rejected'?badge('Rejected'):''}</div><div class="portal-card">${accepted?`<div class="portal-accepted"><div style="font-size:25px">✓</div><h2>Quote accepted</h2><p style="font-size:11px">Your acceptance has been recorded.</p></div>`:doc}${!accepted&&!['Rejected','Expired'].includes(q.status)?`<div class="portal-actions"><button class="btn primary" data-public-accept="${esc(token)}" data-demo="${demo}">${icon('check')} Accept quote</button><button class="btn danger" data-public-reject="${esc(token)}" data-demo="${demo}">Decline</button><button class="btn" data-action="portal-question" data-email="${esc(publicQuote.company?.email||'')}" data-number="${esc(q.number)}">Ask a question</button><button class="btn" data-action="print-quote">${icon('download')} Download PDF</button></div><p style="font-size:9px;color:#8993a1;line-height:1.6;margin-top:14px">Acceptance records a name, email and response time. It is not a certified electronic signature.</p>`:''}${q.status==='Rejected'?`<div class="portal-accepted" style="background:#fdf4f4;color:#ac5155"><h2>Quote declined</h2><p style="font-size:11px">Your response has been recorded.</p></div>`:''}</div><p style="text-align:center;font-size:9px;color:#9aa2ae;margin:17px">Questions? Contact ${esc(publicQuote.company?.email||'')}</p></div></div>`;}
  function publicDocument(q){const t=q.totals;return `<div class="paper"><div class="paper-brand"><div><div class="paper-logo"><span class="brand-mark">${icon('file',17)}</span>${esc(q.company?.name||'')}</div><div class="paper-tag">${esc(q.company?.address||'')}</div></div><div><div class="quote-word">QUOTATION</div><div class="quote-meta">${esc(q.number)}<br>Valid until ${niceDate(q.expiry)}</div></div></div><div class="paper-parties"><div><div class="paper-label">Prepared for</div><strong>${esc(q.customer?.name||'Customer')}</strong><p>${esc(q.customer?.contact||'')}</p></div><div><div class="paper-label">Prepared by</div><strong>${esc(q.company?.name||'')}</strong><p>${esc(q.company?.email||'')}<br>${esc(q.company?.phone||'')}</p></div></div><h2>${esc(q.title)}</h2><table><thead><tr><th>ITEM / DESCRIPTION</th><th>QTY</th><th>UNIT PRICE</th><th>TAX</th><th class="right">AMOUNT</th></tr></thead><tbody>${q.items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><div style="margin-top:4px">${esc(i.description||'')}</div></td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>${money(i.price,q.currency)}</td><td>${+i.tax||0}%</td><td class="right">${money(i.qty*i.price,q.currency)}</td></tr>`).join('')}</tbody></table><div class="paper-totals"><div><span>Subtotal after discount</span><span>${money(t.subtotal,q.currency)}</span></div><div><span>Tax</span><span>${money(t.tax,q.currency)}</span></div><div><span>Total ${esc(q.currency)}</span><span>${money(t.total,q.currency)}</span></div></div><div class="paper-terms"><strong>Payment</strong> · ${esc(q.terms?.payment||'')}<br><strong>Delivery</strong> · ${esc(q.terms?.delivery||'')}<br>${esc(q.terms?.notes||'')}</div><div class="paper-footer"><span>${esc(q.company?.name||'')}</span><span>${esc(q.number)} · Customer copy</span></div></div>`;}
  function toast(message,error=false){const region=document.getElementById('toast-region');if(!region)return;const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.textContent=message;region.appendChild(el);setTimeout(()=>el.remove(),3200);}
  function audit(action,object,actor='Sarah Mitchell'){db.events.unshift({id:crypto.randomUUID(),action,object,at:new Date().toISOString(),actor});}
  function csvDownload(filename,rows){const csv=rows.map(row=>row.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href);}
  function openCustomer(id){const c=db.customers.find(x=>x.id===id);if(!c)return;const qs=db.quotes.filter(q=>q.customerId===id);const won=qs.filter(q=>['Accepted','Won'].includes(q.status)).reduce((a,q)=>a+quoteMath(q).total,0);showModal(c.name,`<div class="detail-kv"><div><span>Contact</span><strong>${esc(c.contact||'—')}</strong></div><div><span>Industry</span><strong>${esc(c.industry||'—')}</strong></div><div><span>Email</span><strong>${esc(c.email||'—')}</strong></div><div><span>Phone</span><strong>${esc(c.phone||'—')}</strong></div><div class="field full"><span>Address</span><strong>${esc(c.address||'—')}</strong></div><div class="field full"><span>Notes</span><strong>${esc(c.notes||'—')}</strong></div></div><hr style="border:0;border-top:1px solid var(--line);margin:17px 0"><div class="customer-stat"><span>Quotations</span><b>${qs.length}</b></div><div class="customer-stat"><span>Won value</span><b>${money(won)}</b></div>${qs.length?`<div style="margin-top:12px">${qs.map(q=>`<div class="follow-row"><div class="follow-info"><strong>${esc(q.number)} · ${esc(q.title)}</strong><small>${badge(q.status)} &nbsp; ${money(quoteMath(q).total,q.currency)}</small></div><button class="btn" data-preview-quote="${q.id}">Open</button></div>`).join('')}</div>`:''}`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-new-quote-customer="${id}">New quote</button>`);}
  function openRfq(id){const r=getRFQ(id);if(!r)return;showModal(r.title,`<div class="detail-kv"><div><span>RFQ number</span><strong>${esc(r.number)}</strong></div><div><span>Customer</span><strong>${esc(customerName(r.customerId))}</strong></div><div><span>Received</span><strong>${niceDate(r.received)}</strong></div><div><span>Deadline</span><strong>${niceDate(r.deadline)}</strong></div><div><span>Priority</span><strong>${esc(r.priority)}</strong></div><div><span>Status</span><strong>${badge(r.status)}</strong></div><div class="field full"><span>Notes</span><strong>${esc(r.notes||'—')}</strong></div></div>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn" data-edit-rfq="${id}">Edit RFQ</button><button class="btn primary" data-convert-rfq="${id}">Make quote</button>`);}
  function addFollowupModal(){const quotes=db.quotes.filter(q=>!['Rejected','Expired'].includes(q.status));if(!quotes.length){toast('Create a quote before adding a follow-up.','error');return;}showModal('Add follow-up',`<form class="form-grid" id="follow-form">${field('Quotation','f-quote',quotes[0].id,'select',{options:quotes.map(q=>[q.id,`${q.number} · ${customerName(q.customerId)}`]),full:true})}${field('Task','f-title','Check in on quotation','text',{required:true,full:true})}${field('Due date','f-date',dateOffset(3),'date',{required:true,full:true})}${field('Note','f-note','','textarea',{full:true})}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-followup">Add follow-up</button>`);}
  function aiDraft(){const c=getCustomer(quoteDraft.customerId),m=quoteMath(quoteDraft);const text=`Subject: Following up on ${quoteDraft.number}\n\nHello ${c?.contact||'there'},\n\nI wanted to check in on our quotation ${quoteDraft.number} for ${quoteDraft.title||'your request'}, totaling ${money(m.total,quoteDraft.currency)}. Please let me know if you would like any adjustments or have questions about the proposed scope.\n\nI’m happy to help.\n\nBest,\n${db.settings.company}`;showModal('Follow-up draft',`<p style="font-size:10px;color:#788394;line-height:1.6">A local template draft based only on the quote and saved customer fields. No AI service is connected.</p><div class="field"><label for="follow-draft">Edit before using</label><textarea id="follow-draft" style="height:210px">${esc(text)}</textarea></div>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="copy-followup">Copy text</button>`);}
  function parseItems(text){const lines=text.split(/\n|;|,(?=\s*\d)/).map(s=>s.trim()).filter(Boolean);return lines.map(line=>{const match=line.match(/(?:^|\b)(\d+(?:\.\d+)?)\s+(?:x\s*)?(.+)/i);if(!match)return null;const qty=+match[1],name=match[2].replace(/[.,]$/,'').trim();const p=db.products.find(x=>x.name.toLowerCase().includes(name.toLowerCase())||name.toLowerCase().includes(x.name.toLowerCase())||x.sku.toLowerCase()===name.toLowerCase());return p?itemFromProduct(p,qty):{name,sku:'',description:'Review and complete item details',qty,unit:'each',cost:0,price:0,tax:+db.settings.tax||0};}).filter(Boolean);}
  async function saveQuote(){const q=quoteDraft; q.title=document.getElementById('q-title').value.trim();q.customerId=document.getElementById('q-customer').value;q.currency=document.getElementById('q-currency').value;q.created=document.getElementById('q-date').value;q.expiry=document.getElementById('q-expiry').value;q.payment=document.getElementById('q-payment').value.trim();q.delivery=document.getElementById('q-delivery').value.trim();q.discount=Math.max(0,+document.getElementById('q-discount').value||0);q.notes=document.getElementById('q-notes').value.trim();const inputs=document.querySelectorAll('[data-item]');for(const el of inputs){const i=q.items[+el.dataset.item],key=el.dataset.key;if(['qty','cost','price','tax'].includes(key))i[key]=Math.max(0,+el.value||0);else i[key]=el.value.trim();}if(!q.title||!q.customerId||!q.items.length||q.items.some(i=>!i.name||i.qty<=0)){toast('Add a title, customer and valid line items before saving.','error');return;}if(q.discount>q.items.reduce((a,i)=>a+i.qty*i.price,0)){toast('Discount cannot exceed the line subtotal.','error');return;}try{if(account){const result=await api('/api/quotes',{method:'POST',body:JSON.stringify(q)});Object.assign(q,result.item);if(result.item.token)q.token=result.item.token;if(q.id){const ix=db.quotes.findIndex(x=>x.id===q.id);if(ix>=0)db.quotes[ix]=q;}else db.quotes.unshift(q);if(q.rfqId){const r=getRFQ(q.rfqId);if(r){r.status='Quoted';await api('/api/rfqs',{method:'POST',body:JSON.stringify(r)});}}}else{const existing=q.id?getQuote(q.id):null;if(existing){Object.assign(existing,q);audit('Quote edited',q.number);}else{q.id=crypto.randomUUID();db.quotes.unshift(q);audit('Quote created',q.number);if(q.rfqId){const r=getRFQ(q.rfqId);if(r)r.status='Quoted';}}save();}toast('Quotation saved.');page='Quotations';quoteDraft=null;render();}catch(e){toast(e.message,'error');}}
  function convertRfq(id){const r=getRFQ(id);if(!r)return;modal.close();newQuote(r);}
  async function saveRfq(){const editId=document.getElementById('r-edit-id').value;const record={id:editId||crypto.randomUUID(),number:editId?getRFQ(editId).number:`RFQ-${new Date().getFullYear()}-${String(db.rfqs.length+1).padStart(3,'0')}`,title:document.getElementById('r-title').value.trim(),customerId:document.getElementById('r-customer').value,received:document.getElementById('r-received').value,deadline:document.getElementById('r-deadline').value,status:document.getElementById('r-status').value,priority:document.getElementById('r-priority').value,source:document.getElementById('r-source').value.trim()||'Manual',notes:document.getElementById('r-notes').value.trim()};if(!record.title||!record.customerId){toast('Add an RFQ title and customer.','error');return;}try{if(account){const result=await api('/api/rfqs',{method:'POST',body:JSON.stringify(record)});Object.assign(record,result.item);}if(editId){Object.assign(getRFQ(editId),record);audit('RFQ edited',record.number);}else{db.rfqs.unshift(record);audit('RFQ created',record.number);}save();modal.close();toast(editId?'RFQ updated.':'RFQ created.');page='RFQs';render();}catch(e){toast(e.message,'error');}}
  async function saveCustomer(){const name=document.getElementById('c-name').value.trim();if(!name){toast('Company name is required.','error');return;}const c={id:crypto.randomUUID(),name,contact:document.getElementById('c-contact').value.trim(),email:document.getElementById('c-email').value.trim(),phone:document.getElementById('c-phone').value.trim(),industry:document.getElementById('c-industry').value.trim(),address:document.getElementById('c-address').value.trim(),notes:document.getElementById('c-notes').value.trim()};try{if(account)Object.assign(c,(await api('/api/customers',{method:'POST',body:JSON.stringify(c)})).item);db.customers.unshift(c);audit('Customer created',c.name);save();modal.close();toast('Customer added.');if(page==='Quotations'&&quoteDraft){quoteDraft.customerId=c.id;renderQuoteEditor();}else{page='Customers';render();}}catch(e){toast(e.message,'error');}}
  async function saveProduct(){const name=document.getElementById('p-name').value.trim();const price=Math.max(0,+document.getElementById('p-price').value||0),cost=Math.max(0,+document.getElementById('p-cost').value||0);if(!name){toast('Item name is required.','error');return;}const id=document.getElementById('p-edit-id').value;const p={id:id||crypto.randomUUID(),name,sku:document.getElementById('p-sku').value.trim(),category:document.getElementById('p-category').value.trim(),unit:document.getElementById('p-unit').value.trim()||'each',cost,price,description:document.getElementById('p-description').value.trim()};try{if(account)Object.assign(p,(await api('/api/products',{method:'POST',body:JSON.stringify(p)})).item);if(id)Object.assign(db.products.find(x=>x.id===id),p);else db.products.unshift(p);audit(id?'Product edited':'Product created',p.name);save();modal.close();toast('Catalog item saved.');page='Products & services';render();}catch(e){toast(e.message,'error');}}
  async function saveFollowup(){const title=document.getElementById('f-title').value.trim();if(!title){toast('Add a follow-up task title.','error');return;}const f={id:crypto.randomUUID(),quoteId:document.getElementById('f-quote').value,title,due:document.getElementById('f-date').value,status:'Pending',note:document.getElementById('f-note').value.trim()};try{if(account)Object.assign(f,(await api('/api/followups',{method:'POST',body:JSON.stringify(f)})).item);db.followups.unshift(f);audit('Follow-up created',getQuote(f.quoteId)?.number||'Quote');save();modal.close();toast('Follow-up added.');page='Follow-ups';render();}catch(e){toast(e.message,'error');}}
