  function saveImported(){const text=document.getElementById('rfq-text').value.trim();if(!text){toast('Paste RFQ content first.','error');return;}const items=parseItems(text);const title=text.split(/[\n.]/)[0].slice(0,75)||'Imported customer request';const r={id:crypto.randomUUID(),number:`RFQ-${new Date().getFullYear()}-${String(db.rfqs.length+1).padStart(3,'0')}`,title,customerId:document.getElementById('import-customer').value,received:dateOffset(0),deadline:dateOffset(7),status:'New',priority:'Normal',source:'Pasted text',notes:text,items};db.rfqs.unshift(r);audit('RFQ imported',r.number);save();modal.close();toast(`RFQ created${items.length?` with ${items.length} suggested item${items.length===1?'':'s'}`:''}. Review before quoting.`);page='RFQs';render();if(items.length)setTimeout(()=>convertRfq(r.id),100);}
  function acceptQuote(id){const q=getQuote(id);if(!q)return;const body=`<p style="font-size:11px;color:#657185;line-height:1.6">Confirm you agree to quotation ${esc(q.number)} and its stated terms.</p><form id="accept-form" class="form-grid">${field('Your name','a-name','','text',{required:true,full:true})}${field('Business email','a-email','','email',{required:true,full:true})}<label style="grid-column:1/-1;font-size:10px;color:#465267;display:flex;gap:8px;align-items:flex-start"><input id="a-agree" type="checkbox" style="margin:1px 0 0"/> I agree to the quotation and terms listed above.</label></form>`;showModal('Accept quotation',body,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-confirm-accept="${id}">Confirm acceptance</button>`);}
  function confirmAccept(id){const q=getQuote(id);const name=document.getElementById('a-name').value.trim(),email=document.getElementById('a-email').value.trim();if(!name||!email||!document.getElementById('a-agree').checked){toast('Enter your name and email, then agree to the terms.','error');return;}q.status='Accepted';q.acceptedBy=name;q.acceptedEmail=email;q.acceptedAt=new Date().toISOString();audit('Quote accepted',q.number,name);const r=getRFQ(q.rfqId);if(r)r.status='Won';save();modal.close();toast('Acceptance recorded.');renderPortal(q.token);}
